#!/bin/bash
# ============================================================
# 奥登科 ERP · odk_mrp_calc（物料需求运算）模块 线上部署脚本
# 用法：在服务器上任意目录执行:  bash odk_mrp_calc_update.sh
# 动作：解出模块 → 拷贝到 deploy_odoo/addons → 重启 Odoo 容器
# ============================================================
set -e
[ -d /www/wwwroot/deploy_odoo ] || { echo "!! 未找到 /www/wwwroot/deploy_odoo，请确认部署目录"; exit 1; }
cd /www/wwwroot
echo '== 还原模块包 =='
echo '' | base64 -d > odk_mrp_calc.tar.gz
tar zxf odk_mrp_calc.tar.gz
cp -r odk_mrp_calc deploy_odoo/addons/
rm -rf odk_mrp_calc odk_mrp_calc.tar.gz
ls deploy_odoo/addons/odk_mrp_calc/
echo '== 重启 Odoo 容器（加载新模块） =='
cd deploy_odoo
docker compose restart odoo
sleep 10
code=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:8069/web/login || true)
echo "Odoo HTTP: ${code:-无响应}"
echo '============================================================'
echo ' 模块文件已部署，Odoo 已重启。'
echo ' 请回到对话窗口告知技术，远程完成模块安装与验证。'
echo '============================================================'
